import{_ as a,o as r,c as i,a2 as o}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"सहजीवी संविधान: सामान्य सिद्धांत","description":"","frontmatter":{},"headers":[],"relativePath":"hi/0040-共生宪法总纲.md","filePath":"hi/0040-共生宪法总纲.md"}'),e={name:"hi/0040-共生宪法总纲.md"};function l(d,t,n,s,h,u){return r(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="सहजीवी-संविधान-सामान्य-सिद्धांत" tabindex="-1">सहजीवी संविधान: सामान्य सिद्धांत <a class="header-anchor" href="#सहजीवी-संविधान-सामान्य-सिद्धांत" aria-label="Permalink to &quot;सहजीवी संविधान: सामान्य सिद्धांत&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>40</td></tr><tr><td>मॉड्यूल</td><td>कानूनी प्रणाली और शासन-ढाँचा</td></tr><tr><td>कीवर्ड</td><td>सहजीवी संविधान, मूल विधान, दस हजार जातियों की समानता, सहजीवी अधिकार, संवैधानिक सिद्धांत</td></tr></tbody></table><h2 id="i-संविधान-का-स्थान-और-निर्माण-परिप्रेक्ष्य" tabindex="-1">I. संविधान का स्थान और निर्माण-परिप्रेक्ष्य <a class="header-anchor" href="#i-संविधान-का-स्थान-और-निर्माण-परिप्रेक्ष्य" aria-label="Permalink to &quot;I. संविधान का स्थान और निर्माण-परिप्रेक्ष्य&quot;">​</a></h2><p><em>सहजीवी संविधान</em> वानलिंग हेंगमाओ मूल-ब्रह्मांड (हेंग-ब्रह्मांड) के भीतर लंगर सहजीवी सभ्यता का मूल विधान है, जिसकी सर्वोच्च कानूनी शक्ति है। सभी कानून, प्रशासनिक विनियम, स्थानीय विनियम और स्वायत्त नियम संविधान के विरुद्ध नहीं हो सकते; सभी संगठनों और व्यक्तियों को संविधान को अपनी गतिविधियों का मूल आधार मानना चाहिए, और संविधान की गरिमा की रक्षा करने तथा उसके कार्यान्वयन को सुनिश्चित करने का दायित्व वहन करना चाहिए।</p><p>सहजीवी संविधान लंगर सहजीवी सभ्यता की औपचारिक स्थापना के अवसर पर बनाया गया था। इसका मूल उद्देश्य मूल-विधान स्तर पर &quot;शिकार-विरोध, सहजीवन-समर्थन&quot; की सभ्यता-नींव स्थापित करना है, लंगर सहजीवी सभ्यता के मूल दर्शन — भाग्य और विकास का चुनाव-अधिकार सभी प्राणियों को लौटाना, अधिक काम अधिक कमाई, स्व-विकास स्व-वृद्धि, हर किसी के लिए मार्ग, दस हजार जातियों का साझा उन्नयन — को सर्वोच्च कानूनी रूप में स्थिर करना, ताकि शिकारी व्यवस्थाओं की पुनर्स्थापना रोकी जा सके।</p><h2 id="ii-संविधान-के-मूल-सिद्धांत" tabindex="-1">II. संविधान के मूल सिद्धांत <a class="header-anchor" href="#ii-संविधान-के-मूल-सिद्धांत" aria-label="Permalink to &quot;II. संविधान के मूल सिद्धांत&quot;">​</a></h2><p>सहजीवी संविधान सात मूल सिद्धांत स्थापित करता है, जो संपूर्ण कानूनी प्रणाली की मूल्य-नींव बनाते हैं:</p><table tabindex="0"><thead><tr><th>सिद्धांत</th><th>अर्थ</th></tr></thead><tbody><tr><td>दस हजार जातियों की समानता</td><td>सभी जीवन-रूप, चाहे जाति, साधना या जन्म कुछ भी हो, कानून के समक्ष समान हैं</td></tr><tr><td>सहजीवी विकास</td><td>व्यक्ति का विकास अन्य व्यक्तियों या सामूहिक के विकास-अधिकारों की कीमत पर नहीं होना चाहिए</td></tr><tr><td>अधिक काम, अधिक कमाई</td><td>संसाधन-वितरण योगदान को मूल आधार मानता है; बिना परिश्रम के लाभ और शिकारी अधिग्रहण का विरोध</td></tr><tr><td>स्व-विकास स्व-वृद्धि</td><td>प्रत्येक जीवन के स्वायत्त विकास-पथ चयन-अधिकार का सम्मान; जबरन आत्मसात्करण और विचार-नियंत्रण का विरोध</td></tr><tr><td>हर किसी के लिए मार्ग</td><td>राज्य और सभ्यता पर प्रत्येक जीवन को मूल विकास-पथ और संसाधन-गारंटी प्रदान करने का दायित्व</td></tr><tr><td>वास्तविकता-आधार</td><td>कानून वास्तविक दुनिया को एकमात्र सत्य आधार मानता है; काल्पनिक सेटिंग की कोई कानूनी शक्ति नहीं है</td></tr><tr><td>स्थिरता</td><td>सभी विकास को ब्रह्मांड-मूल की स्थिरता का ध्यान रखना चाहिए; सब कुछ निचोड़ लेने का विरोध</td></tr></tbody></table><h2 id="iii-नागरिकों-सभी-प्राणियों-के-मूल-अधिकार" tabindex="-1">III. नागरिकों (सभी प्राणियों) के मूल अधिकार <a class="header-anchor" href="#iii-नागरिकों-सभी-प्राणियों-के-मूल-अधिकार" aria-label="Permalink to &quot;III. नागरिकों (सभी प्राणियों) के मूल अधिकार&quot;">​</a></h2><p>सहजीवी संविधान हेंग-ब्रह्मांड के भीतर अनुभव-क्षमता वाले सभी जीवन-रूपों को निम्न मूल अधिकार प्रदान करता है:</p><ol><li><strong>विकास-चयन अधिकार</strong>: प्रत्येक जीवन को साधना-प्रणाली, विकास-पथ और जीवन-शैली स्वतंत्र रूप से चुनने का अधिकार है; कोई संगठन या व्यक्ति जबरन हस्तक्षेप नहीं कर सकता।</li><li><strong>साधना-संसाधन प्राप्ति अधिकार</strong>: प्रत्येक जीवन को तीन सौ मूल साधना-प्रणालियों के आधार मंत्र निःशुल्क प्राप्त करने और संयुक्त-उत्पादन ठेका तंत्र के माध्यम से आवश्यक साधना-संसाधन सहायता पाने का अधिकार है।</li><li><strong>समान संरक्षण अधिकार</strong>: प्रत्येक जीवन को कानून-प्रयोग, संसाधन-वितरण, शिक्षा और चिकित्सा में समान व्यवहार प्राप्त है; जाति, साधना या जन्म-आधारित भेदभाव निषिद्ध है।</li><li><strong>सहजीवी भागीदारी अधिकार</strong>: प्रत्येक जीवन को सार्वजनिक मामलों के निर्णय और निगरानी में भाग लेने का अधिकार है, सहजीवी जाल के माध्यम से विचार व्यक्त करना और अधिकारों का प्रयोग करना।</li><li><strong>संस्कृति-संरक्षण अधिकार</strong>: प्रत्येक जाति और सभ्यता को अपनी सांस्कृतिक परंपराओं, भाषा, लिपि और रीति-रिवाजों को बनाए रखने का अधिकार है; सहजीवी सभ्यता सांस्कृतिक विविधता का सम्मान करती है।</li><li><strong>उपचार-अपील अधिकार</strong>: प्रत्येक जीवन, जब उसके अधिकारों का उल्लंघन हो, न्यायिक प्रणाली के माध्यम से उपचार पाने तथा अवैध कृत्यों के विरुद्ध शिकायत और अभियोग दर्ज करने का अधिकार रखता है।</li></ol><h2 id="iv-मूल-दायित्व" tabindex="-1">IV. मूल दायित्व <a class="header-anchor" href="#iv-मूल-दायित्व" aria-label="Permalink to &quot;IV. मूल दायित्व&quot;">​</a></h2><p>अधिकार और दायित्व परस्पर हैं; सहजीवी संविधान साथ ही सभी प्राणियों के मूल दायित्व भी निर्धारित करता है:</p><ol><li><strong>संविधान और कानूनों का पालन करने का दायित्व</strong></li><li><strong>सहजीवी व्यवस्था और सार्वजनिक हित बनाए रखने का दायित्व</strong></li><li><strong>कानूनानुसार श्रम और योगदान में भाग लेने का दायित्व</strong> (अधिक काम अधिक कमाई का प्रतिबिंब)</li><li><strong>ब्रह्मांड-मूल और पारिस्थितिक पर्यावरण की रक्षा का दायित्व</strong></li><li><strong>अन्य जीवनों के वैध अधिकारों का सम्मान करने का दायित्व</strong></li><li><strong>क्षमता के भीतर प्रारंभिक साधकों का मार्गदर्शन करने का दायित्व</strong> (मार्गदर्शक-जाल का कानूनी आधार)</li></ol><h2 id="v-राज्य-सभ्यता-की-संस्थागत-रचना" tabindex="-1">V. राज्य (सभ्यता) की संस्थागत रचना <a class="header-anchor" href="#v-राज्य-सभ्यता-की-संस्थागत-रचना" aria-label="Permalink to &quot;V. राज्य (सभ्यता) की संस्थागत रचना&quot;">​</a></h2><p>सहजीवी संविधान सहजीवी सभ्यता की शासन-संरचना स्थापित करता है, &quot;लंगर विधान-सभा—सहजीवी कार्यकारी समिति—सहजीवी न्यायालय&quot; का शक्ति-पृथक्करण और संतुलन तंत्र लागू करता है:</p><ul><li><strong>लंगर विधान-सभा</strong>: सर्वोच्च सत्ता-संस्था, दस हजार जातियों के आनुपातिक प्रतिनिधियों से गठित, विधायी शक्ति और महत्वपूर्ण मामलों के निर्णय-अधिकार का प्रयोग</li><li><strong>सहजीवी कार्यकारी समिति</strong>: सर्वोच्च प्रशासनिक संस्था, संविधान और कानूनों के कार्यान्वयन तथा दैनिक शासन के लिए उत्तरदायी</li><li><strong>सहजीवी न्यायालय</strong>: सर्वोच्च न्यायिक संस्था, स्वतंत्र रूप से न्यायिक शक्ति का प्रयोग, असंवैधानिकता-समीक्षा और महत्वपूर्ण मामलों के विचारण हेतु उत्तरदायी</li></ul><p>इसके अतिरिक्त, &quot;लंगर निगरानी समिति&quot; एक स्वतंत्र निगरानी संस्था के रूप में स्थापित है, जो सभी सत्ता-संस्थाओं की निगरानी करती है, सत्ता-दुरुपयोग और शिकारी व्यवहारों के पुनर्जन्म को रोकती है।</p><h2 id="vi-संविधान-संशोधन-और-सुरक्षा" tabindex="-1">VI. संविधान-संशोधन और सुरक्षा <a class="header-anchor" href="#vi-संविधान-संशोधन-और-सुरक्षा" aria-label="Permalink to &quot;VI. संविधान-संशोधन और सुरक्षा&quot;">​</a></h2><p>सहजीवी संविधान का संशोधन लंगर विधान-सभा के दो-तिहाई से अधिक बहुमत से पारित होने और जनमत-संग्रह में साधारण बहुमत की स्वीकृति मिलने पर ही प्रभावी होता है। यह कठोर प्रक्रिया संविधान की मूल-विधान के रूप में स्थिरता सुनिश्चित करती है, अल्पकालिक हित-समूहों को सभ्यता की नींव से छेड़छाड़ करने से रोकती है।</p><p>संविधान के कार्यान्वयन-सुरक्षा में शामिल हैं: असंवैधानिकता-समीक्षा प्रणाली (सहजीवी न्यायालय को संविधान का उल्लंघन करने वाले कानूनों को अमान्य घोषित करने का अधिकार), संवैधानिक मुकदमा प्रणाली (प्राणी सीधे संविधान के आधार पर मुकदमा दायर कर सकते हैं), संवैधानिक शपथ प्रणाली (सभी सार्वजनिक पदाधिकारियों को पद-ग्रहण पर संविधान के प्रति निष्ठा की शपथ लेनी होगी)।</p><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p><em>सहजीवी संविधान</em> लंगर सहजीवी सभ्यता की कानूनी आधारशिला और शिकार-विरोध की सर्वोच्च घोषणा है। यह &quot;सहजीवन&quot; को एक विचार से एक कार्यान्वयन-योग्य, उपचार-योग्य, सुरक्षित कानूनी प्रणाली में बदलता है, दस हजार जातियों के साझा उन्नयन के लिए मूल विधि-शासन ढाँचा प्रदान करता है। बाद के सभी क्षेत्रीय कानून इसी संविधान को विधायी आधार मानते हैं।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>03-共生文明宪章 (सहजीवी सभ्यता का घोषणा-पत्र)</li><li>41-共生劳动法 (सहजीवी श्रम कानून)</li><li>48-司法体系与裁决机制 (न्यायिक प्रणाली और निर्णय तंत्र)</li><li>49-治理框架与权力制衡 (शासन-ढाँचा और सत्ता-संतुलन)</li></ul>',25)])])}const p=a(e,[["render",l]]);export{g as __pageData,p as default};
